package com.minhnb.finvera_be.alert.entity;
import tools.jackson.databind.JsonNode;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="alert_notification") public class AlertNotificationEntity{@Id private UUID id;@Column(name="owner_id")private UUID ownerId;@Column(name="alert_id")private UUID alertId;@Column(name="evaluation_id")private UUID evaluationId;@Column(name="episode_sequence")private Long episodeSequence;@Column(name="event_key")private String eventKey;private String title;private String message;@JdbcTypeCode(SqlTypes.JSON)@Column(name="condition_snapshot",columnDefinition="jsonb")private JsonNode conditionSnapshot;@JdbcTypeCode(SqlTypes.JSON)@Column(name="evidence_snapshot",columnDefinition="jsonb")private JsonNode evidence;@Column(name="triggered_at")private Instant triggeredAt;@Column(name="delivered_at")private Instant deliveredAt;@Column(name="read_at")private Instant readAt;protected AlertNotificationEntity(){}public AlertNotificationEntity(UUID id,UUID ownerId,UUID alertId,UUID evaluationId,Long seq,String eventKey,String title,String message,JsonNode condition,JsonNode evidence,Instant now){this.id=id;this.ownerId=ownerId;this.alertId=alertId;this.evaluationId=evaluationId;episodeSequence=seq;this.eventKey=eventKey;this.title=title;this.message=message;conditionSnapshot=condition;this.evidence=evidence;triggeredAt=now;deliveredAt=now;}public UUID getId(){return id;}public UUID getAlertId(){return alertId;}public String getTitle(){return title;}public String getMessage(){return message;}public JsonNode getConditionSnapshot(){return conditionSnapshot;}public JsonNode getEvidence(){return evidence;}public Instant getTriggeredAt(){return triggeredAt;}public Instant getDeliveredAt(){return deliveredAt;}public Instant getReadAt(){return readAt;}public void markRead(Instant at){if(readAt==null)readAt=at;}}
